class Cat {
    static int count = 0;
    String name;

    Cat(String name) {
        this.name = name;
        count = count + 1;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Cat[] cats = new Cat[n];
